export default function Breadcrumb({ trail }) {
  return (
    <nav className="breadcrumb" aria-label="Breadcrumb">
      <ol>
        {trail.map((step, i) => {
          const isLast = i === trail.length - 1
          return (
            <li key={step}>
              {isLast ? (
                <span aria-current="page">{step}</span>
              ) : (
                <>
                  <a href="#">{step}</a>
                  <span className="separator" aria-hidden="true">/</span>
                </>
              )}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

// Simple stylized shoe illustration rendered as inline SVG so we don't
// need external image assets. The view angle changes per photo.
export default function ShoeImage({ colorHex, photoIndex }) {
  const id = `sole-${photoIndex}-${colorHex.replace('#', '')}`
  return (
    <svg viewBox="0 0 400 260" role="img" aria-label="Trail Runner 2 shoe photo">
      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#4a4f57" />
          <stop offset="100%" stopColor="#2a2d33" />
        </linearGradient>
      </defs>
      <rect width="400" height="260" fill={photoIndex % 2 ? '#f4f4f2' : '#eceae5'} />
      {photoIndex === 2 ? (
        // Sole view
        <g transform="rotate(-12 200 130)">
          <path
            d="M60 130 Q70 70 140 65 L280 60 Q340 62 345 110 Q348 150 300 165 L120 185 Q65 185 60 130 Z"
            fill={`url(#${id})`}
          />
          {Array.from({ length: 14 }).map((_, i) => (
            <circle key={i} cx={95 + (i % 7) * 35} cy={i < 7 ? 105 : 145} r="12" fill={colorHex} />
          ))}
        </g>
      ) : photoIndex === 3 ? (
        // Heel detail
        <g>
          <path
            d="M120 200 Q115 90 175 60 Q230 38 275 75 Q300 100 295 200 Z"
            fill={colorHex}
          />
          <rect x="120" y="185" width="180" height="30" rx="10" fill={`url(#${id})`} />
          <text x="180" y="140" fill="#fff" fontSize="26" fontWeight="bold">TR2</text>
        </g>
      ) : (
        // Side / top view
        <g transform={photoIndex === 1 ? 'scale(1,0.85) translate(0,25)' : undefined}>
          <path
            d="M45 175 Q40 120 95 105 L175 88 Q215 55 250 62 Q300 72 330 105 Q365 118 360 155 L355 175 Z"
            fill={colorHex}
          />
          <path
            d="M45 175 L355 175 Q360 200 340 205 L70 205 Q45 200 45 175 Z"
            fill={`url(#${id})`}
          />
          <path d="M170 95 L200 120 M195 88 L225 113 M220 82 L250 107" stroke="#ffffff99" strokeWidth="7" />
          <circle cx="320" cy="140" r="9" fill="#ffffff55" />
        </g>
      )}
    </svg>
  )
}

