import ShoeImage from './ShoeImage.jsx'

export default function Gallery({ photos, photoIndex, onPrev, onNext, colorHex }) {
  const photo = photos[photoIndex]
  return (
    <div className="gallery">
      <div className="gallery-main">
        <ShoeImage colorHex={colorHex} photoIndex={photoIndex} />
        <button className="gallery-arrow prev" onClick={onPrev} aria-label="Previous photo">
          ‹
        </button>
        <button className="gallery-arrow next" onClick={onNext} aria-label="Next photo">
          ›
        </button>
      </div>
      <div className="gallery-meta">
        <span>{photo.caption}</span>
        <span>
          {photoIndex + 1} / {photos.length}
        </span>
      </div>
      <div className="gallery-dots">
        {photos.map((p, i) => (
          <button
            key={p.id}
            className={i === photoIndex ? 'dot active' : 'dot'}
            onClick={() => (i > photoIndex ? onNext() : onPrev())}
            aria-label={`Photo ${i + 1}`}
          />
        ))}
      </div>
    </div>
  )
}

