import { useEffect, useState } from 'react'
import { sizeChart, recommendSize } from '../data.js'

export default function SizeGuideModal({ onClose }) {
  const [cm, setCm] = useState('')
  const [system, setSystem] = useState('us')

  // Block body scroll while open — the modal must be closed to continue.
  useEffect(() => {
    document.body.style.overflow = 'hidden'
    return () => {
      document.body.style.overflow = ''
    }
  }, [])

  useEffect(() => {
    const onKey = (e) => e.key === 'Escape' && onClose()
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onClose])

  const recommended = recommendSize(parseFloat(cm), system)

  return (
    <div className="modal-overlay" role="dialog" aria-modal="true" aria-label="Size guide">
      <div className="modal">
        <div className="modal-header">
          <h2>Size Guide</h2>
          <button className="modal-close" onClick={onClose} aria-label="Close size guide">
            ×
          </button>
        </div>
        <div className="modal-body">
          <label className="field">
            Foot length (cm)
            <input
              type="number"
              min="20"
              max="35"
              step="0.1"
              value={cm}
              onChange={(e) => setCm(e.target.value)}
              placeholder="e.g. 26.5"
            />
          </label>
          <div className="unit-toggle" role="group" aria-label="Size system">
            <button
              className={system === 'us' ? 'active' : ''}
              onClick={() => setSystem('us')}
            >
              US
            </button>
            <button
              className={system === 'eu' ? 'active' : ''}
              onClick={() => setSystem('eu')}
            >
              EU
            </button>
          </div>
          {cm && (
            <p className="recommendation">
              {recommended
                ? <>Your recommended size: <strong>{recommended}</strong></>
                : 'Enter a valid foot length.'}
            </p>
          )}
          <table className="size-chart">
            <thead>
              <tr>
                <th>Foot (cm)</th>
                <th>US</th>
                <th>EU</th>
              </tr>
            </thead>
            <tbody>
              {sizeChart.map((row) => (
                <tr key={row.cm}>
                  <td>{row.cm.toFixed(1)}</td>
                  <td>{row.us}</td>
                  <td>{row.eu}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="modal-footer">
          <button className="btn primary" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  )
}

