import { useState } from 'react'
import { product } from './data.js'
import Header from './components/Header.jsx'
import Breadcrumb from './components/Breadcrumb.jsx'
import Gallery from './components/Gallery.jsx'
import SizeGuideModal from './components/SizeGuideModal.jsx'

export default function App() {
  const [cartCount, setCartCount] = useState(0)
  const [photoIndex, setPhotoIndex] = useState(0)
  const [color, setColor] = useState(product.colors[0])
  const [size, setSize] = useState(null)
  const [sizeMenuOpen, setSizeMenuOpen] = useState(false)
  const [sizeGuideOpen, setSizeGuideOpen] = useState(false)
  const [quantity, setQuantity] = useState(1)
  const [wishlisted, setWishlisted] = useState(false)
  const [notice, setNotice] = useState(null) // { type: 'ok' | 'error', text }

  const numPhotos = product.photos.length
  const prevPhoto = () => setPhotoIndex((i) => (i - 1 + numPhotos) % numPhotos)
  const nextPhoto = () => setPhotoIndex((i) => (i + 1) % numPhotos)

  const clampQty = (n) => {
    if (isNaN(n)) return 1
    return Math.min(10, Math.max(1, Math.floor(n)))
  }

  const addToCart = () => {
    if (!size) {
      setNotice({ type: 'error', text: 'Please select a size first.' })
      return
    }
    setCartCount((c) => c + quantity)
    setNotice({
      type: 'ok',
      text: `Added ${quantity} × ${product.name} (${color.label}, ${size.label}) to your cart.`,
    })
  }

  const pickSize = (s) => {
    if (!s.inStock) return
    setSize(s)
    setSizeMenuOpen(false)
    if (notice?.type === 'error') setNotice(null)
  }

  return (
    <div className="page">
      <Header store={product.store} cartCount={cartCount} />

      <main className="container">
        <Breadcrumb trail={product.breadcrumb} />

        <div className="product-layout">
          <Gallery
            photos={product.photos}
            photoIndex={photoIndex}
            onPrev={prevPhoto}
            onNext={nextPhoto}
            colorHex={color.hex}
          />

          <section className="buy-panel">
            <h1>{product.name}</h1>
            <p className="tagline">{product.tagline}</p>
            <p className="rating">
              ★ {product.rating} · {product.reviewCount} reviews
            </p>

            <div className="price-row">
              <span className="price">${product.price.toFixed(2)}</span>
              <span className="price-info">
                ⓘ
                <span className="tooltip" role="tooltip">
                  Price includes all applicable taxes.
                </span>
              </span>
            </div>

            <div className="option-block">
              <span className="option-label">
                Color: <strong>{color.label}</strong>
              </span>
              <div className="swatches">
                {product.colors.map((c) => (
                  <button
                    key={c.id}
                    className={c.id === color.id ? 'swatch selected' : 'swatch'}
                    style={{ backgroundColor: c.hex }}
                    onClick={() => setColor(c)}
                    aria-label={`Color ${c.label}`}
                    aria-pressed={c.id === color.id}
                  />
                ))}
              </div>
            </div>

            <div className="option-block size-block">
              <div className="size-header">
                <span className="option-label">
