              </button>
              {sizeMenuOpen && (
                <ul className="size-menu">
                  {product.sizes.map((s) => (
                    <li key={s.id}>
                      <button
                        className={
                          (s.id === size?.id ? 'selected' : '') +
                          (s.inStock ? '' : ' sold-out')
