  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  background: #fff;
}

.size-menu button {
  width: 100%;
  padding: 10px 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
}

.size-menu button.selected {
  border-color: var(--ink);
  background: var(--ink);
  color: #fff;
}

