  color: #b6bac1;
  background: repeating-linear-gradient(
    45deg,
    #fff,
    #fff 6px,
    #f3f4f6 6px,
    #f3f4f6 12px
  );
  cursor: not-allowed;
}

.sold-out-note {
  display: block;
  font-size: 11px;
}

