  width: 40px;
  height: 40px;
  border: none;
  background: #f9fafb;
  font-size: 18px;
}

.quantity input {
  width: 56px;
  height: 40px;
  border: none;
  text-align: center;
  font-size: 16px;
  -moz-appearance: textfield;
}

.quantity input::-webkit-outer-spin-button,
.quantity input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

/* Actions */
.actions {
  display: flex;
  gap: 12px;
  align-items: stretch;
}

.btn.primary {
  background: var(--accent);
