  letter-spacing: 1px;
  margin: 0 0 12px;
}

.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 14px;
}

.footer-col a:hover {
  color: #fff;
}

.copyright {
  max-width: 1100px;
  margin: 32px auto 0;
  font-size: 13px;
  color: #9ca3af;
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 24px;
}

.modal {
  background: #fff;
  border-radius: 12px;
  width: 100%;
  max-width: 480px;
  max-height: 85vh;
  overflow-y: auto;
  padding: 24px;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modal-header h2 {
  margin: 0;
}

.modal-close {
  background: none;
  border: none;
  font-size: 28px;
  line-height: 1;
}

.modal-body {
  padding: 16px 0;
}

.field {
  display: block;
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 16px;
}

.field input {
  display: block;
  width: 100%;
  margin-top: 6px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 16px;
}

.unit-toggle {
  display: inline-flex;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}

.unit-toggle button {
  border: none;
  background: #fff;
  padding: 8px 20px;
}

.unit-toggle button.active {
  background: var(--ink);
  color: #fff;
}

.recommendation {
  background: #ecfdf3;
  border: 1px solid #b8e6cb;
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 14px;
}

