  width: 100%;
  text-align: left;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  display: flex;
  justify-content: space-between;
}

.size-menu {
  list-style: none;
  margin: 6px 0 0;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 8px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  background: #fff;
}

.size-menu button {
  width: 100%;
  padding: 10px 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #fff;
}

.size-menu button.selected {
  border-color: var(--ink);
  background: var(--ink);
  color: #fff;
}

.size-menu button.sold-out {
  color: #b6bac1;
  background: repeating-linear-gradient(
    45deg,
    #fff,
    #fff 6px,
    #f3f4f6 6px,
    #f3f4f6 12px
  );
  cursor: not-allowed;
}

.sold-out-note {
  display: block;
  font-size: 11px;
}

/* Quantity */
.quantity {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}

.quantity button {
  width: 40px;
  height: 40px;
  border: none;
  background: #f9fafb;
  font-size: 18px;
}

.quantity input {
  width: 56px;
  height: 40px;
  border: none;
  text-align: center;
  font-size: 16px;
  -moz-appearance: textfield;
}

.quantity input::-webkit-outer-spin-button,
.quantity input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

/* Actions */
.actions {
  display: flex;
  gap: 12px;
  align-items: stretch;
}

.btn.primary {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 14px 28px;
  font-weight: 700;
  font-size: 16px;
}

.btn.primary:hover {
  filter: brightness(0.92);
}

.add-to-cart {
  flex: 1;
}

.wishlist {
  width: 52px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
  font-size: 24px;
  color: var(--muted);
}

.wishlist.active {
  color: var(--accent);
  border-color: var(--accent);
}

.wishlist-note {
  font-size: 13px;
  color: var(--muted);
  margin: 8px 0 0;
}

.notice {
  margin: 16px 0 0;
  padding: 12px 14px;
  border-radius: 8px;
  font-size: 14px;
}

.notice.ok {
  background: #ecfdf3;
  color: #15653b;
  border: 1px solid #b8e6cb;
}

.notice.error {
  background: #fef2f2;
  color: #a02c2c;
  border: 1px solid #f3c2c2;
}

/* Info tabs */
.info-tabs {
  border-top: 1px solid var(--line);
  padding: 32px 0;
}

.tab-bar {
  display: flex;
  gap: 24px;
  border-bottom: 1px solid var(--line);
}

.tab {
  background: none;
  border: none;
  padding: 10px 4px;
  font-weight: 600;
  color: var(--muted);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
}

.tab.active {
  color: var(--ink);
  border-bottom-color: var(--ink);
}

.tab-panel {
  padding: 20px 4px;
  line-height: 1.6;
}

.tab-panel ul {
  margin: 0;
  padding-left: 20px;
}

.reviews article {
  margin-bottom: 20px;
}

.stars {
  color: #f5a623;
  margin: 0 0 4px;
}

.reviewer {
  color: var(--muted);
  font-size: 14px;
}

/* FAQ */
.faq {
  border-top: 1px solid var(--line);
  padding: 32px 0 64px;
}

.faq h2 {
  margin-top: 0;
}

.faq-item {
  border-bottom: 1px solid var(--line);
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  padding: 16px 4px;
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  font-size: 16px;
}

.faq-answer {
  margin: 0;
  padding: 0 4px 16px;
  color: var(--muted);
  line-height: 1.6;
}

/* Footer */
.footer {
  background: #17191d;
  color: #d1d5db;
  padding: 48px 24px 24px;
}

.footer-inner {
  max-width: 1100px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.footer-col h3 {
  color: #fff;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: 0 0 12px;
}

.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 14px;
}

.footer-col a:hover {
  color: #fff;
}

.copyright {
  max-width: 1100px;
  margin: 32px auto 0;
  font-size: 13px;
  color: #9ca3af;
}

/* Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 100;
  padding: 24px;
}

.modal {
  background: #fff;
  border-radius: 12px;
  width: 100%;
  max-width: 480px;
  max-height: 85vh;
  overflow-y: auto;
  padding: 24px;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.modal-header h2 {
  margin: 0;
}

.modal-close {
  background: none;
  border: none;
  font-size: 28px;
  line-height: 1;
}

.modal-body {
  padding: 16px 0;
}

.field {
  display: block;
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 16px;
}

.field input {
  display: block;
  width: 100%;
  margin-top: 6px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 16px;
}

.unit-toggle {
  display: inline-flex;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}

.unit-toggle button {
  border: none;
  background: #fff;
  padding: 8px 20px;
}

.unit-toggle button.active {
  background: var(--ink);
  color: #fff;
}

.recommendation {
  background: #ecfdf3;
  border: 1px solid #b8e6cb;
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 14px;
}

.size-chart {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
  font-size: 14px;
}

.size-chart th,
.size-chart td {
  text-align: left;
  padding: 8px;
  border-bottom: 1px solid var(--line);
}

.size-chart th {
  color: var(--muted);
  font-weight: 600;
}

.modal-footer {
  display: flex;
  justify-content: flex-end;
}

